const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D');
}
const raw = String(source.rawText || message.text || payload.text || '').trim();
const text = normalize(source.text || raw);
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const calendarId = source.calendarId || payload.calendarId || 'primary';
const tzOffset = '+07:00';
const now = new Date();
function pad(n) { return String(n).padStart(2, '0'); }
function buildIso(date, hour, minute) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(hour)}:${pad(minute)}:00${tzOffset}`;
}
function startOfDay(date) { const d = new Date(date); d.setHours(0,0,0,0); return d; }
function addDays(base, days) { const d = new Date(base); d.setDate(d.getDate() + days); return d; }
function nextWeekday(base, targetDow, nextWeek = false) {
  const d = startOfDay(base);
  let diff = (targetDow - d.getDay() + 7) % 7;
  if (diff === 0) diff = 7;
  if (nextWeek) diff += 7;
  d.setDate(d.getDate() + diff);
  return d;
}
function parseTargetDate(text, base) {
  if (/cuoi tuan sau/.test(text)) return startOfDay(nextWeekday(base, 6, true));
  if (/cuoi tuan nay/.test(text)) return startOfDay(nextWeekday(base, 6, false));
  const weekdayMatch = text.match(/thu\s*(2|3|4|5|6|7)|chu nhat/);
  if (weekdayMatch) {
    const targetDow = weekdayMatch[1] ? Number(weekdayMatch[1]) - 1 : 0;
    return startOfDay(nextWeekday(base, targetDow, /tuan sau/.test(text)));
  }
  if (/ngay kia|mot ngay nua/.test(text)) return startOfDay(addDays(base, 2));
  if (/ngay mai|mai/.test(text)) return startOfDay(addDays(base, 1));
  return startOfDay(base);
}
const date = parseTargetDate(text, now);
const rangeMatch = raw.match(/(\d{1,2})(?:[:hg](\d{1,2}))?\s*(?:-|den|toi)\s*(\d{1,2})(?:[:hg](\d{1,2}))?/i);
const startMatch = raw.match(/(?:luc|vao|tu)?\s*(\d{1,2})(?:[:hg](\d{1,2}))?/i);
let start = '';
let end = '';
if (rangeMatch) {
  let sh = Number(rangeMatch[1]);
  let sm = Number(rangeMatch[2] || 0);
  let eh = Number(rangeMatch[3]);
  let em = Number(rangeMatch[4] || 0);
  if (/\b(chieu|toi)\b/.test(text) && sh < 12) sh += 12;
  if (/\b(chieu|toi)\b/.test(text) && eh < 12) eh += 12;
  start = buildIso(date, sh, sm);
  end = buildIso(date, eh, em);
} else if (startMatch || /sang|chieu|toi|trua/.test(text)) {
  let sh = startMatch ? Number(startMatch[1]) : (/sang/.test(text) ? 9 : /trua/.test(text) ? 12 : /toi/.test(text) ? 19 : 14);
  let sm = startMatch ? Number(startMatch[2] || 0) : 0;
  if (/\b(chieu|toi)\b/.test(text) && sh < 12) sh += 12;
  start = buildIso(date, sh, sm);
  let durationMinutes = 60;
  const durationMatch = text.match(/(\d+)\s*(tieng|gio|h|phut)/);
  if (durationMatch) durationMinutes = Number(durationMatch[1]) * (/phut/.test(durationMatch[2]) ? 1 : 60);
  const endDate = new Date(start);
  endDate.setMinutes(endDate.getMinutes() + durationMinutes);
  end = buildIso(endDate, endDate.getHours(), endDate.getMinutes());
}
const isReady = Boolean(start && end);
const response = '🗓 <b>Kiểm tra lịch rảnh</b>\n\nBạn hãy nhập như:\n- tôi rảnh lúc 15h hôm nay không\n- check lịch rảnh 9h-10h mai\n- availability chiều mai 2 tiếng\n- rảnh thứ 2 tuần sau lúc 14h không';
return [{ json: { ...source, payload, message, rawText: raw, text, chatId, calendarId, start, end, isReady, response } }];

const source = $('Chuan Bi Kiem Tra Ranh').item.json;
const rows = $input.all().map(item => item.json || {});
const available = rows.length === 0;
let text = '🗓 <b>Kiểm tra lịch rảnh</b>\n\n';
text += `🕒 ${source.start} → ${source.end}\n`;
text += available ? '✅ Khung giờ này đang rảnh.' : '❌ Khung giờ này đã có lịch bận.';
if (!available) {
  text += '\n\nCác lịch đang chồng khung giờ:';
  for (let i = 0; i < rows.length; i++) {
    const event = rows[i];
    const title = event.summary || 'Không có tiêu đề';
    const start = event.start?.dateTime || event.start?.date || '';
    text += `\n- ${title} (${start})`;
  }
}
return [{ json: { chatId: source.chatId, text } }];
